// Spatial (grid-measured) density term for the liquid EOS. DISABLED: with
// particle lattices coarser than the grid, the estimator aliases above rest
// density inside perfectly packed blocks and the Tait ^7 stiffness turns the
// overshoot into an explosion at spawn (verified: both blocks blasted apart
// by t=0.14). The plumbing stays for a stabilized estimator to re-enable.
const MLS_MPM_GRID_DENSITY_PRESSURE_ENABLED = false;
const mlsMpmGridUpdateActiveGridWgsl = createActiveGridUpdateWgsl();
const mlsMpmGridUpdateCompactMechanicsWgsl = createCompactMechanicsGridUpdateWgsl();

export function createFusedP2gParamsArray(
  gridSpec,
  particleCount,
  dt,
  internalPressureScale = 1,
  schroederLevelFilter = null,
  schroederActiveNodeFilter = null,
  gridDensityPressureEnabled = false,
  ambientPressurePa = 0,
  externalGaugePressurePa = 0,
  externalGaugePressureEnabled = false,
  mechanicsFieldMutation = null,
  pressureRequiredConsumerMask =
    SCHROEDER_SPATIAL_MECHANICS_FIELD_PRESSURE_CONSUMER_LOCAL,
  mechanicsFieldTemporalCoarsePredictor = null
) {
  const filterEnabled = schroederLevelFilter?.enabled === true;
  const activeNodeFilterEnabled = schroederActiveNodeFilter?.enabled === true;
  const activeSourceV2 =
    schroederActiveNodeFilter?.activeSourceP2gEnabled === true;
  const temporalCoarseEnabled =
    mechanicsFieldTemporalCoarsePredictor?.enabled === true;
  const temporalCoarseSuccessorDt = temporalCoarseEnabled
    ? finiteNumber(
        mechanicsFieldTemporalCoarsePredictor?.successorThetaDt,
        Number.NaN
      )
    : 0;
  if (temporalCoarseEnabled && (
    !activeSourceV2
    || !(temporalCoarseSuccessorDt > finiteNumber(dt, 0))
  )) {
    throw new RangeError(
      'temporal coarse predictor requires ActiveSource-v2 and a successor theta dt greater than the current projection dt'
    );
  }
  const buffer = new ArrayBuffer(activeSourceV2
    ? FUSED_ACTIVE_SOURCE_V2_P2G_PARAMS_BYTES
    : FUSED_P2G_PARAMS_BYTES);
  const view = new DataView(buffer);
  view.setUint32(0, particleCount, true);
  view.setUint32(4, gridSpec.gridNodeCount, true);
  view.setUint32(8, gridSpec.gridDims[0], true);
  view.setUint32(12, gridSpec.gridDims[1], true);
  view.setUint32(16, gridSpec.gridDims[2], true);
  view.setUint32(20, gridSpec.shift, true);
  view.setFloat32(24, gridSpec.gridSpacingM, true);
  view.setFloat32(28, gridSpec.invGridSpacingM, true);
  view.setFloat32(32, finiteNumber(dt, 0), true);
  view.setUint32(36, 0, true);
  view.setFloat32(40, finiteNumber(internalPressureScale, 1), true);
  view.setUint32(44, filterEnabled ? 1 : 0, true);
  view.setInt32(48, filterEnabled ? Math.round(finiteNumber(schroederLevelFilter.selectedLevel, 0)) : 0, true);
  view.setUint32(52, Math.max(1, Math.round(finiteNumber(
    schroederLevelFilter?.assignmentStrideFloats,
    SCHROEDER_LEVEL_ASSIGNMENT_FLOATS
  ))), true);
  view.setUint32(56, activeNodeFilterEnabled ? 1 : 0, true);
  view.setUint32(60, Math.max(0, Math.round(finiteNumber(
    schroederActiveNodeFilter?.storageGeneration,
    0
  ))), true);
  view.setUint32(64, gridDensityPressureEnabled ? 1 : 0, true);
  // ambient_pressure_pa: gauge reference for the ideal-gas partial pressure
  // (0 = vacuum box). See P2gProjectionParams in ulg-gpu-abi/src/wgsl.js.
  view.setFloat32(68, Math.max(0, finiteNumber(ambientPressurePa, 0)), true);
  view.setFloat32(72, finiteNumber(externalGaugePressurePa, 0), true);
  view.setUint32(76, externalGaugePressureEnabled === true ? 1 : 0, true);
  view.setUint32(80, Math.max(0, Math.round(finiteNumber(
    schroederActiveNodeFilter?.positionEpoch,
    0
  ))), true);
  view.setUint32(84, Math.max(0, Math.round(finiteNumber(
    schroederActiveNodeFilter?.topologyEpoch,
    0
  ))), true);
  view.setUint32(88, schroederActiveNodeFilter?.required === true ? 1 : 0, true);
  view.setUint32(92, Math.max(0, Math.round(finiteNumber(
    schroederActiveNodeFilter?.generationId,
    0
  ))), true);
  view.setUint32(96, Math.max(0, Math.round(finiteNumber(
    schroederActiveNodeFilter?.deviceOrdinal,
    0
  ))), true);
  view.setUint32(100, Math.max(0, Math.round(finiteNumber(
    schroederActiveNodeFilter?.laneOrdinal,
    0
  ))), true);
  view.setUint32(104, Math.max(0, Math.round(finiteNumber(
    schroederActiveNodeFilter?.leaseToken,
    0
  ))), true);
  view.setUint32(108, Math.max(0, Math.round(finiteNumber(
    schroederActiveNodeFilter?.sourceFamilyId,
    0
  ))), true);
  view.setUint32(112, Math.max(0, Math.round(finiteNumber(
    schroederActiveNodeFilter?.physicsTick,
    0
  ))), true);
  view.setUint32(116, Math.max(0, Math.round(finiteNumber(
    schroederActiveNodeFilter?.physicsSubstep,
    0
  ))), true);
  view.setUint32(120, Math.max(0, Math.round(finiteNumber(
    schroederActiveNodeFilter?.chartEpoch,
    0
  ))), true);
  view.setUint32(124, Math.max(0, Math.round(finiteNumber(
    schroederActiveNodeFilter?.levelEpoch,
    0
  ))), true);
  view.setUint32(128, Math.max(0, Math.round(finiteNumber(
    schroederActiveNodeFilter?.supportEpoch,
    0
  ))), true);
  view.setUint32(132, schroederLevelFilter?.spatialEvidenceEnabled === true ? 1 : 0, true);
  view.setUint32(136, schroederActiveNodeFilter?.mechanicsViewEnabled === true
    ? Math.max(0, Math.round(finiteNumber(
        schroederActiveNodeFilter.sourceRowLayoutId,
        0
      )))
    : 0, true);
  view.setUint32(140, schroederActiveNodeFilter?.mechanicsViewEnabled === true
    ? Math.max(0, Math.round(finiteNumber(
        schroederActiveNodeFilter.completionOrdinal,
        0
      )))
    : 0, true);
  view.setUint32(144, Math.max(0, Math.round(finiteNumber(
    mechanicsFieldMutation?.expectedOrdinal,
    0
  ))), true);
  view.setUint32(148, Math.max(0, Math.round(finiteNumber(
    mechanicsFieldMutation?.outputOrdinal,
    0
  ))), true);
  view.setUint32(152, Math.max(0, Math.round(finiteNumber(
    mechanicsFieldMutation?.expectedEncoding,
    0
  ))), true);
  view.setUint32(156, Math.max(0, Math.round(finiteNumber(
    pressureRequiredConsumerMask,
    SCHROEDER_SPATIAL_MECHANICS_FIELD_PRESSURE_CONSUMER_LOCAL
  ))), true);
  if (activeSourceV2) {
    view.setUint32(160, schroederActiveNodeFilter.activeSourcePhysicalCapacity, true);
    view.setUint32(164, schroederActiveNodeFilter.activeSourceActiveCapacity, true);
    view.setUint32(168, schroederActiveNodeFilter.activeSourceViewWordLength, true);
    view.setUint32(
      172,
      schroederActiveNodeFilter.activeSourceActiveToPhysicalOffsetWords,
      true
    );
    view.setUint32(
      176,
      schroederActiveNodeFilter.activeSourcePhysicalToActiveOffsetWords,
      true
    );
    view.setUint32(180, schroederActiveNodeFilter.activeSourceFingerprint, true);
    view.setUint32(184, schroederActiveNodeFilter.activeSourceDispatchXLimit, true);
    view.setUint32(188, SCHROEDER_SPATIAL_ACTIVE_SOURCE_VIEW_HEADER_WORDS, true);
    view.setUint32(192, temporalCoarseEnabled ? 1 : 0, true);
    view.setFloat32(196, temporalCoarseSuccessorDt, true);
    view.setUint32(200, 0, true);
    view.setUint32(204, 0, true);
  }
  return buffer;
}

function createFusedActiveP2gParamsArray(
  gridSpec,
  particleCount,
  dt,
  internalPressureScale,
  activeGridDispatch,
  schroederLevelFilter = null,
  schroederActiveNodeFilter = null,
  gridDensityPressureEnabled = false,
  ambientPressurePa = 0,
  externalGaugePressurePa = 0,
  externalGaugePressureEnabled = false
) {
  const buffer = new ArrayBuffer(FUSED_ACTIVE_P2G_PARAMS_BYTES);
  new Uint8Array(buffer).set(new Uint8Array(createFusedP2gParamsArray(
    gridSpec,
    particleCount,
    dt,
    internalPressureScale,
    schroederLevelFilter,
    schroederActiveNodeFilter,
    gridDensityPressureEnabled,
    ambientPressurePa,
    externalGaugePressurePa,
    externalGaugePressureEnabled
  )));
  const view = new DataView(buffer);
  view.setUint32(144, activeGridDispatch.activeStart[0], true);
  view.setUint32(148, activeGridDispatch.activeStart[1], true);
  view.setUint32(152, activeGridDispatch.activeStart[2], true);
  view.setUint32(156, activeGridDispatch.activeCount[0], true);
  view.setUint32(160, activeGridDispatch.activeCount[1], true);
  view.setUint32(164, activeGridDispatch.activeCount[2], true);
  view.setUint32(168, activeGridDispatch.activeNodeCount, true);
  view.setUint32(172, 0, true);
  return buffer;
}

function fusedCanonicalSpatialAuthorityError(status, reason) {
  const error = new Error(`Canonical fused resident mechanics rejected: ${reason}`);
  error.code = 'ERR_CANONICAL_SPATIAL_AUTHORITY_REJECTED';
  error.status = status;
  return error;
}

function assertCanonicalSpatialMechanicalProposalGeneration({
  device,
  generation,
  selectedLevel
} = {}) {
  if (
    typeof selectedLevel !== 'number'
    || !Number.isInteger(selectedLevel)
    || selectedLevel < -0x8000_0000
    || selectedLevel > 0x7fff_ffff
  ) {
    throw fusedCanonicalSpatialAuthorityError(
      'canonical-spatial-selected-level-rejected',
      'an exact i32 selected Schroeder level is required'
    );
  }
  const execution = generation?.execution || null;
  const directoryV2 = execution?.schema === ULG_SCHROEDER_SPATIAL_EPOCH_V2_SCHEMA
    && execution?.abiVersion === SCHROEDER_SPATIAL_EPOCH_V2_VERSION
    && execution?.reverseEncoding
      === SCHROEDER_SPATIAL_EPOCH_V2_REVERSE_CELL_PLUS_ONE;
  const activeSourceView = directoryV2
    ? (generation?.activeSourceView ?? execution?.activeSourceView ?? null)
    : null;
  const directoryBuffer = execution?.directoryBuffer || null;
  const evidenceBuffer = execution?.evidenceBuffer || null;
  const directoryMismatch = directoryBuffer
    ? webGpuDeviceMismatchInfo({ buffer: directoryBuffer, device })
    : { mismatch: false };
  const evidenceMismatch = evidenceBuffer
    ? webGpuDeviceMismatchInfo({ buffer: evidenceBuffer, device })
    : { mismatch: false };
  const evidenceBufferTooSmall = Number.isFinite(Number(evidenceBuffer?.size))
    && Number(evidenceBuffer.size) < SCHROEDER_SPATIAL_EPOCH_WITH_MECHANICS_EVIDENCE_BYTES;
  const overlayRejected = generation?.source?.phaseVolumeAssignmentOverlayEnabled === true;
  let activeSourceRejected = false;
  if (directoryV2) {
    let activeSourceAdmission = { admitted: false };
    try {
      activeSourceAdmission = validateSchroederSpatialActiveSourceViewDescriptor(
        activeSourceView,
        {
          physicalSourceCount: execution?.physicalSourceCount,
          physicalSourceCapacity: execution?.physicalSourceCapacity,
          activeSourceCapacity: execution?.activeSourceCapacity,
          sourceBuffer: execution?.sourceBuffer,
          activeSourceViewBuffer: execution?.activeSourceViewBuffer,
          generationId: execution?.generationId,
          deviceOrdinal: execution?.deviceOrdinal,
          laneOrdinal: execution?.laneOrdinal,
          leaseToken: execution?.leaseToken,
          sourceFamilyId: execution?.sourceFamilyId,
          storageGeneration: execution?.storageGeneration,
          physicsTick: execution?.physicsTick,
          physicsSubstep: execution?.physicsSubstep,
          positionEpoch: execution?.positionEpoch,
          topologyEpoch: execution?.topologyEpoch,
          chartEpoch: execution?.chartEpoch,
          levelEpoch: execution?.levelEpoch,
          supportEpoch: execution?.supportEpoch,
          buildOrdinal: execution?.buildOrdinal
        }
      );
    } catch {
      activeSourceAdmission = { admitted: false };
    }
    activeSourceRejected = activeSourceAdmission.admitted !== true
      || generation?.activeSourceViewRuntime !== activeSourceView?.ownerRuntime
      || activeSourceView?.ownerRuntime?.isExecutionSubmitted?.(activeSourceView)
        !== true
      || execution?.activeSourceView !== activeSourceView
      || execution?.activeSourceViewBuffer
        !== activeSourceView?.activeSourceViewBuffer;
  }
  const schemaRejected = generation?.schema
      !== SCHROEDER_SPATIAL_EPOCH_GENERATION_SCHEMA
    || (
      execution?.schema !== SCHROEDER_SPATIAL_EPOCH_SCHEMA
      && !directoryV2
    )
    || activeSourceRejected;
  const queryProfileRejected = execution?.sourceAdapterId
      !== SCHROEDER_SPATIAL_SOURCE_ADAPTER_EXACT_NEAR_QUERY
    || execution?.exactNearQueryProfile?.ready !== true
    || execution?.queryGeometryEvidence !== execution.exactNearQueryProfile;
  const released = execution?.released === true;
  const status = directoryMismatch.mismatch || evidenceMismatch.mismatch
    ? 'canonical-spatial-directory-rejected-device'
    : (evidenceBufferTooSmall
        ? 'canonical-spatial-directory-rejected-evidence-capacity'
        : (overlayRejected
            ? 'canonical-spatial-directory-rejected-overlay-authority'
            : (schemaRejected
                ? 'canonical-spatial-directory-rejected-schema'
                : (queryProfileRejected
                    ? 'canonical-spatial-directory-rejected-query-geometry'
                    : (released
                        ? 'canonical-spatial-directory-rejected-released-generation'
                        : null)))));
  if (
    status
    || generation?.selected !== true
    || generation?.ready !== true
    || execution?.submitPerformed !== true
    || !directoryBuffer
    || !evidenceBuffer
  ) {
    const resolvedStatus = status
      || 'canonical-spatial-directory-requested-but-unavailable';
    throw fusedCanonicalSpatialAuthorityError(
      resolvedStatus,
      `spatial authority was rejected before proposal submission: ${resolvedStatus}`
    );
  }
  return true;
}

function createFusedSchroederLevelAssignmentBinding({
  device,
  schroederLevelAssignment = null,
  schroederSelectedLevel = null,
  canonicalSpatialAuthority = false,
  schroederSpatialDirectory = null,
  observeCanonicalSpatialAuthority = false,
  labelPrefix = 'ulg-mls-mpm-fused'
} = {}) {
  if (canonicalSpatialAuthority === true) {
    if (
      typeof schroederSelectedLevel !== 'number'
      || !Number.isInteger(schroederSelectedLevel)
      || schroederSelectedLevel < -0x8000_0000
      || schroederSelectedLevel > 0x7fff_ffff
    ) {
      throw fusedCanonicalSpatialAuthorityError(
        'canonical-spatial-selected-level-rejected',
        'an exact i32 selected Schroeder level is required'
      );
    }
    const selectedLevel = schroederSelectedLevel;
    const buffer = schroederSpatialDirectory?.evidenceBuffer ?? null;
    if (!buffer) {
      throw fusedCanonicalSpatialAuthorityError(
        'canonical-spatial-directory-rejected-evidence-capacity',
        'generation-owned authority evidence storage is required'
      );
    }
    return {
      enabled: true,
      selectedLevel,
      assignmentStrideFloats: SCHROEDER_LEVEL_ASSIGNMENT_FLOATS,
      assignmentBuffer: buffer,
      ownsAssignmentBuffer: false,
      retainedAssignmentBuffer: false,
      assignmentBufferByteLength: 0,
      assignmentBufferSource: null,
      authorityBindingBuffer: buffer,
      authorityBindingMode: 'canonical-spatial-epoch',
      oldLevelAssignmentLookupRemoved: true,
      spatialEvidenceEnabled: observeCanonicalSpatialAuthority === true,
      spatialEvidenceBufferByteLength: SCHROEDER_MECHANICS_SPATIAL_AUTHORITY_EVIDENCE_BYTES
    };
  }
  const selectedLevel = Math.round(finiteNumber(
    schroederSelectedLevel ?? schroederLevelAssignment?.selectedLevel,
    0
  ));
  const assignmentStrideFloats = Math.max(1, Math.round(finiteNumber(
    schroederLevelAssignment?.assignmentStrideFloats,
    SCHROEDER_LEVEL_ASSIGNMENT_FLOATS
  )));
  if (assignmentStrideFloats !== SCHROEDER_LEVEL_ASSIGNMENT_FLOATS) {
    throw new RangeError('Fused resident mechanics Schroeder filtering requires the current level-assignment row layout');
  }
  if (!schroederLevelAssignment) {
    const buffer = sharedZeroPlaceholderBuffer(
      device,
      `${labelPrefix}-empty-schroeder-level-assignments`,
      SCHROEDER_LEVEL_ASSIGNMENT_FLOATS * Float32Array.BYTES_PER_ELEMENT,
      GPU_BUFFER_USAGE.STORAGE | GPU_BUFFER_USAGE.COPY_DST
    );
    return {
      enabled: false,
      selectedLevel: 0,
      assignmentStrideFloats,
      assignmentBuffer: buffer,
      // Shared per device now, so destroying it would pull the binding out
      // from under every later substep. Only the dummy row is shared; the
      // uploaded assignment buffer below is still owned per call.
      ownsAssignmentBuffer: false,
      retainedAssignmentBuffer: false,
      assignmentBufferByteLength: SCHROEDER_LEVEL_ASSIGNMENT_FLOATS * Float32Array.BYTES_PER_ELEMENT,
      assignmentBufferSource: 'dummy-schroeder-level-assignment-row',
      authorityBindingBuffer: buffer,
      authorityBindingMode: 'precanonical-unfiltered',
      oldLevelAssignmentLookupRemoved: false,
      spatialEvidenceEnabled: false,
      spatialEvidenceBufferByteLength: 0
    };
  }
  const retainedBuffer = schroederLevelAssignment.assignmentBuffer ?? schroederLevelAssignment.buffer ?? null;
  if (retainedBuffer) {
    return {
      enabled: true,
      selectedLevel,
      assignmentStrideFloats,
      assignmentBuffer: retainedBuffer,
      ownsAssignmentBuffer: false,
      retainedAssignmentBuffer: true,
      assignmentBufferByteLength: schroederLevelAssignment.assignmentBufferByteLength
        ?? schroederLevelAssignment.assignmentByteLength
        ?? 0,
      assignmentBufferSource: 'retained-schroeder-level-assignment-buffer',
      authorityBindingBuffer: retainedBuffer,
      authorityBindingMode: 'precanonical-level-assignment',
      oldLevelAssignmentLookupRemoved: false,
      spatialEvidenceEnabled: false,
      spatialEvidenceBufferByteLength: 0
    };
  }
  const assignments = schroederLevelAssignment.assignments instanceof Float32Array
    ? schroederLevelAssignment.assignments
    : null;
  if (assignments) {
    const buffer = writeGpuBuffer(
      device,
      `${labelPrefix}-schroeder-level-assignments-upload`,
      assignments,
      GPU_BUFFER_USAGE.STORAGE | GPU_BUFFER_USAGE.COPY_DST
    );
    return {
      enabled: true,
      selectedLevel,
      assignmentStrideFloats,
      assignmentBuffer: buffer,
      ownsAssignmentBuffer: true,
      retainedAssignmentBuffer: false,
      assignmentBufferByteLength: assignments.byteLength,
      assignmentBufferSource: 'uploaded-schroeder-level-assignment-rows',
      authorityBindingBuffer: buffer,
      authorityBindingMode: 'precanonical-level-assignment',
      oldLevelAssignmentLookupRemoved: false,
      spatialEvidenceEnabled: false,
      spatialEvidenceBufferByteLength: 0
    };
  }
  throw new TypeError('Fused resident mechanics Schroeder filtering requires retained assignment buffer or assignment rows');
}

function fusedSchroederLevelFilterMetadata(filter = null) {
  return {
    enabled: filter?.enabled === true,
    selectedLevel: filter?.enabled === true ? filter.selectedLevel : null,
    assignmentStrideFloats: filter?.assignmentStrideFloats ?? SCHROEDER_LEVEL_ASSIGNMENT_FLOATS,
    retainedAssignmentBuffer: filter?.retainedAssignmentBuffer === true,
    assignmentBufferByteLength: filter?.assignmentBufferByteLength ?? 0,
    assignmentBufferSource: filter?.assignmentBufferSource ?? null,
    authorityBindingMode: filter?.authorityBindingMode ?? 'precanonical-unfiltered',
    oldLevelAssignmentLookupRemoved: filter?.oldLevelAssignmentLookupRemoved === true,
    spatialEvidenceEnabled: filter?.spatialEvidenceEnabled === true,
    spatialEvidenceBufferByteLength: filter?.spatialEvidenceBufferByteLength ?? 0
  };
}

export function resolveFusedSchroederMechanicsLevelView(
  schroederSpatialEpochGeneration,
  selectedLevel
) {
  const mechanicsLevelViews = Array.isArray(
    schroederSpatialEpochGeneration?.mechanicsLevelViews
  )
    ? schroederSpatialEpochGeneration.mechanicsLevelViews
    : [];
  if (mechanicsLevelViews.length > 0) {
    const normalizedSelectedLevel = Number(selectedLevel);
    const matched = mechanicsLevelViews.find((entry) => (
      Number.isInteger(normalizedSelectedLevel)
      && Number(entry?.selectedLevel) === normalizedSelectedLevel
    )) || null;
    // The historical top-level aliases point at the first compact level. They
    // remain valid for a one-level generation only; using them for a missing
    // level in a two-level generation would silently bind the wrong field.
    const resolved = matched || (
      mechanicsLevelViews.length === 1 ? mechanicsLevelViews[0] : null
    );
    return {
      mechanicsView: resolved?.mechanicsView || null,
      mechanicsViewRuntime: resolved?.mechanicsViewRuntime || null,
      mechanicsViewPublished: resolved
        ? Boolean(resolved.mechanicsView || resolved.mechanicsViewRuntime)
        : mechanicsLevelViews.some((entry) => Boolean(
            entry?.mechanicsView || entry?.mechanicsViewRuntime
          )),
      mechanicsFieldView: resolved?.mechanicsFieldView || null,
      mechanicsFieldViewRuntime: resolved?.mechanicsFieldViewRuntime || null,
      mechanicsFieldViewPublished: resolved
        ? Boolean(
            resolved.mechanicsFieldView || resolved.mechanicsFieldViewRuntime
          )
        : mechanicsLevelViews.some((entry) => Boolean(
            entry?.mechanicsFieldView || entry?.mechanicsFieldViewRuntime
          )),
      mechanicsLevelViewCount: mechanicsLevelViews.length,
      matchedSelectedLevel: matched?.selectedLevel ?? null,
      source: matched
        ? 'generation-mechanics-level-view-exact-match'
        : (resolved
            ? 'generation-mechanics-level-view-one-level-alias'
            : 'generation-mechanics-level-view-missing-exact-match')
    };
  }
  const mechanicsView = schroederSpatialEpochGeneration?.mechanicsView || null;
  const mechanicsViewRuntime =
    schroederSpatialEpochGeneration?.mechanicsViewRuntime || null;
  const mechanicsFieldView =
    schroederSpatialEpochGeneration?.mechanicsFieldView || null;
  const mechanicsFieldViewRuntime =
    schroederSpatialEpochGeneration?.mechanicsFieldViewRuntime || null;
  return {
    mechanicsView,
    mechanicsViewRuntime,
    mechanicsViewPublished: Boolean(mechanicsView || mechanicsViewRuntime),
    mechanicsFieldView,
    mechanicsFieldViewRuntime,
    mechanicsFieldViewPublished: Boolean(
      mechanicsFieldView || mechanicsFieldViewRuntime
    ),
    mechanicsLevelViewCount: mechanicsView || mechanicsFieldView ? 1 : 0,
    matchedSelectedLevel:
      mechanicsView?.selectedLevel ?? mechanicsFieldView?.selectedLevel ?? null,
    source: mechanicsView || mechanicsFieldView
      ? 'generation-one-level-top-level-alias'
      : 'generation-mechanics-level-view-not-published'
  };
}

export function createFusedSchroederActiveNodeBinding({
  device,
  schroederSpatialEpochGeneration = null,
  canonicalSpatialRequired = false,
  gridSpec = null,
  selectedLevel = null,
  particleStateBuffer = null,
  particleIdentityBuffer = null,
  canonicalParticleContinuation = null,
  // Explicit consumer gate for the compact mechanics view. When false the
  // binding presents the plain canonical V1 directory route (full-grid
  // geometry, generation-owned evidence buffer) even when the generation
  // published a compact view; the field/active-source sub-modes derive
  // from the view and turn off with it.
  consumeCompactMechanicsView = true,
  labelPrefix = 'ulg-mls-mpm-fused'
} = {}) {
  const execution = schroederSpatialEpochGeneration?.execution || null;
  const directoryV2 = execution?.schema === ULG_SCHROEDER_SPATIAL_EPOCH_V2_SCHEMA
    && execution?.abiVersion === SCHROEDER_SPATIAL_EPOCH_V2_VERSION
    && execution?.reverseEncoding
      === SCHROEDER_SPATIAL_EPOCH_V2_REVERSE_CELL_PLUS_ONE;
  const activeSourceView = directoryV2
    ? (
        schroederSpatialEpochGeneration?.activeSourceView
        ?? execution?.activeSourceView
        ?? null
      )
    : null;
  const directoryBuffer = execution?.directoryBuffer || null;
  const evidenceBuffer = execution?.evidenceBuffer || null;
  const activeSourceBuffer = activeSourceView?.activeSourceViewBuffer ?? null;
  const mechanicsLevelView = resolveFusedSchroederMechanicsLevelView(
    schroederSpatialEpochGeneration,
    selectedLevel
  );
  const {
    mechanicsView,
    mechanicsViewRuntime,
    mechanicsViewPublished,
    mechanicsFieldView,
    mechanicsFieldViewRuntime,
    mechanicsFieldViewPublished
  } = mechanicsLevelView;
  const directoryDeviceMismatch = directoryBuffer
    ? webGpuDeviceMismatchInfo({ buffer: directoryBuffer, device })
    : { mismatch: false, sourceDeviceId: null, consumerDeviceId: null };
  const evidenceDeviceMismatch = evidenceBuffer
    ? webGpuDeviceMismatchInfo({ buffer: evidenceBuffer, device })
    : { mismatch: false, sourceDeviceId: null, consumerDeviceId: null };
  const activeSourceDeviceMismatch = activeSourceBuffer
    ? webGpuDeviceMismatchInfo({ buffer: activeSourceBuffer, device })
    : { mismatch: false, sourceDeviceId: null, consumerDeviceId: null };
  const deviceMismatch = directoryDeviceMismatch.mismatch
    ? directoryDeviceMismatch
    : (evidenceDeviceMismatch.mismatch
        ? evidenceDeviceMismatch
        : activeSourceDeviceMismatch);
  const evidenceBufferTooSmall = Number.isFinite(Number(evidenceBuffer?.size))
    && Number(evidenceBuffer.size) < SCHROEDER_SPATIAL_EPOCH_WITH_MECHANICS_EVIDENCE_BYTES;
  const continuationStateAdmitted = canonicalParticleContinuation != null
    && canonicalParticleContinuation?.macroAuthority?.generation
      === schroederSpatialEpochGeneration
    && validateSchroederCanonicalParticleContinuation(
      device,
      canonicalParticleContinuation,
      {
        macroAuthority: canonicalParticleContinuation.macroAuthority,
        stateBuffer: particleStateBuffer,
        identityBuffer: particleIdentityBuffer
      }
    );
  let mechanicsViewAdmission = null;
  let mechanicsViewDeviceMismatch = { mismatch: false, sourceDeviceId: null, consumerDeviceId: null };
  let mechanicsViewOwnerAdmitted = false;
  let mechanicsViewShapeAdmitted = false;
  let mechanicsFieldViewAdmission = null;
  let mechanicsFieldViewDeviceMismatch = {
    mismatch: false,
    sourceDeviceId: null,
    consumerDeviceId: null
  };
  let mechanicsFieldViewOwnerAdmitted = false;
  let mechanicsFieldViewShapeAdmitted = false;
  let activeSourceAdmission = null;
  let activeSourceOwnerAdmitted = !directoryV2;
  if (directoryV2) {
    try {
      activeSourceAdmission = validateSchroederSpatialActiveSourceViewDescriptor(
        activeSourceView,
        {
          physicalSourceCount: execution?.physicalSourceCount,
          physicalSourceCapacity: execution?.physicalSourceCapacity,
          activeSourceCapacity: execution?.activeSourceCapacity,
          sourceBuffer: execution?.sourceBuffer,
          activeSourceViewBuffer: execution?.activeSourceViewBuffer,
          generationId: execution?.generationId,
          deviceOrdinal: execution?.deviceOrdinal,
          laneOrdinal: execution?.laneOrdinal,
          leaseToken: execution?.leaseToken,
          sourceFamilyId: execution?.sourceFamilyId,
          storageGeneration: execution?.storageGeneration,
          physicsTick: execution?.physicsTick,
          physicsSubstep: execution?.physicsSubstep,
          positionEpoch: execution?.positionEpoch,
          topologyEpoch: execution?.topologyEpoch,
          chartEpoch: execution?.chartEpoch,
          levelEpoch: execution?.levelEpoch,
          supportEpoch: execution?.supportEpoch,
          buildOrdinal: execution?.buildOrdinal
        }
      );
      activeSourceOwnerAdmitted =
        schroederSpatialEpochGeneration?.activeSourceViewRuntime
          === activeSourceView?.ownerRuntime
        && activeSourceView?.ownerRuntime?.ownsExecution?.(activeSourceView)
          === true
        && activeSourceView?.ownerRuntime?.isExecutionSubmitted?.(
          activeSourceView
        ) === true
        && execution?.activeSourceView === activeSourceView
        && execution?.activeSourceViewBuffer === activeSourceBuffer;
    } catch {
      activeSourceOwnerAdmitted = false;
    }
  }
  if (mechanicsViewPublished) {
    mechanicsViewDeviceMismatch = mechanicsView?.mechanicsViewBuffer
      ? webGpuDeviceMismatchInfo({ buffer: mechanicsView.mechanicsViewBuffer, device })
      : mechanicsViewDeviceMismatch;
    mechanicsViewAdmission = validateSchroederSpatialMechanicsViewDescriptor(
      mechanicsView,
      {
        generationId: execution?.generationId,
        deviceOrdinal: execution?.deviceOrdinal,
        laneOrdinal: execution?.laneOrdinal,
        leaseToken: execution?.leaseToken,
        sourceFamilyId: execution?.sourceFamilyId,
        storageGeneration: execution?.storageGeneration,
        physicsTick: execution?.physicsTick,
        physicsSubstep: execution?.physicsSubstep,
        positionEpoch: execution?.positionEpoch,
        topologyEpoch: execution?.topologyEpoch,
        chartEpoch: execution?.chartEpoch,
        levelEpoch: execution?.levelEpoch,
        supportEpoch: execution?.supportEpoch,
        sourceCount: execution?.sourceCount,
        physicalSourceCount: execution?.physicalSourceCount
          ?? execution?.sourceCount,
        sourceRowLayoutId: execution?.sourceRowLayoutId,
        ...(directoryV2 ? {
          directorySchema: ULG_SCHROEDER_SPATIAL_EPOCH_V2_SCHEMA,
          directoryAbiVersion:
            SCHROEDER_SPATIAL_MECHANICS_VIEW_DIRECTORY_VERSION_V2,
          sourceAuthorityVersion:
            SCHROEDER_SPATIAL_MECHANICS_VIEW_DIRECTORY_VERSION_V2,
          sourceWorkIdentity:
            SCHROEDER_SPATIAL_MECHANICS_VIEW_ACTIVE_WORK_IDENTITY
        } : {}),
        selectedLevel,
        gridNodeCount: gridSpec?.gridNodeCount,
        gridDims: gridSpec?.gridDims,
        gridShift: gridSpec?.shift,
        gridSpacingM: Math.fround(Number(gridSpec?.gridSpacingM))
      }
    );
    try {
      mechanicsViewOwnerAdmitted = mechanicsViewRuntime === mechanicsView?.ownerRuntime
        && mechanicsViewRuntime?.ownsExecution?.(mechanicsView) === true
        && mechanicsViewRuntime?.isExecutionSubmitted?.(mechanicsView) === true
        && schroederSpatialEpochGeneration?.runtime === execution?.ownerRuntime
        && schroederSpatialEpochGeneration?.runtime?.ownsExecution?.(execution) === true
        && schroederSpatialEpochGeneration?.runtime?.isExecutionSubmitted?.(execution)
          === true;
    } catch {
      mechanicsViewOwnerAdmitted = false;
    }
    const expectedByteLength = Number(mechanicsView?.layout?.byteLength);
    const expectedCapacityWords = SCHROEDER_SPATIAL_MECHANICS_VIEW_NODE_OFFSET_WORDS
      + Math.max(0, Math.floor(finiteNumber(gridSpec?.gridNodeCount, 0)));
    mechanicsViewShapeAdmitted = mechanicsView?.schema
        === ULG_SCHROEDER_SPATIAL_MECHANICS_VIEW_SCHEMA
      && mechanicsView?.sourceBuffer === execution?.sourceBuffer
      && (
        schroederSpatialEpochGeneration?.source?.sourceStateBuffer
          === particleStateBuffer
        || continuationStateAdmitted
      )
      && mechanicsView?.directoryBuffer === directoryBuffer
      && (!directoryV2 || (
        mechanicsView?.spatialExecution === execution
        && mechanicsView?.activeSourceView === activeSourceView
        && mechanicsView?.activeSourceViewBuffer === activeSourceBuffer
        && mechanicsView?.activeSourceCountAuthority
          === execution?.activeSourceCountAuthority
      ))
      && mechanicsView?.mechanicsViewBuffer === mechanicsView?.indirectDispatchBuffer
      && mechanicsView?.indirectDispatchOffsetBytes
        === SCHROEDER_SPATIAL_MECHANICS_VIEW_DISPATCH_OFFSET_WORDS * Uint32Array.BYTES_PER_ELEMENT
      && mechanicsView?.completionOrdinal === execution?.buildOrdinal
      && mechanicsView?.layout?.nodeOffsetWords
        === SCHROEDER_SPATIAL_MECHANICS_VIEW_NODE_OFFSET_WORDS
      && mechanicsView?.layout?.headerOffsetWords
        === SCHROEDER_SPATIAL_MECHANICS_VIEW_HEADER_OFFSET_WORDS
      && mechanicsView?.layout?.headerWords
        === SCHROEDER_SPATIAL_MECHANICS_VIEW_HEADER_WORDS
      && mechanicsView?.layout?.dispatchOffsetWords
        === SCHROEDER_SPATIAL_MECHANICS_VIEW_DISPATCH_OFFSET_WORDS
      && mechanicsView?.layout?.nodeCapacity === gridSpec?.gridNodeCount
      && mechanicsView?.layout?.occupancyWordCount
        === Math.ceil(Math.max(0, finiteNumber(gridSpec?.gridNodeCount, 0)) / 32)
      && mechanicsView?.layout?.wordLength === expectedCapacityWords
      && Number.isSafeInteger(expectedByteLength)
      && expectedByteLength === expectedCapacityWords * Uint32Array.BYTES_PER_ELEMENT
      && (!Number.isFinite(Number(mechanicsView?.mechanicsViewBuffer?.size))
        || Number(mechanicsView.mechanicsViewBuffer.size) >= expectedByteLength);
  }
  if (mechanicsFieldViewPublished) {
    const fieldViewDeviceMismatch = mechanicsFieldView?.fieldViewBuffer
      ? webGpuDeviceMismatchInfo({ buffer: mechanicsFieldView.fieldViewBuffer, device })
      : mechanicsFieldViewDeviceMismatch;
    const stableOrderDeviceMismatch = mechanicsFieldView?.stableCandidateOrderBuffer
      ? webGpuDeviceMismatchInfo({
          buffer: mechanicsFieldView.stableCandidateOrderBuffer,
          device
        })
      : mechanicsFieldViewDeviceMismatch;
    mechanicsFieldViewDeviceMismatch = fieldViewDeviceMismatch.mismatch
      ? fieldViewDeviceMismatch
      : stableOrderDeviceMismatch;
    mechanicsFieldViewAdmission = validateSchroederSpatialMechanicsFieldViewDescriptor(
      mechanicsFieldView,
      {
        generationId: execution?.generationId,
        deviceOrdinal: execution?.deviceOrdinal,
        laneOrdinal: execution?.laneOrdinal,
        leaseToken: execution?.leaseToken,
        sourceFamilyId: execution?.sourceFamilyId,
        storageGeneration: execution?.storageGeneration,
        physicsTick: execution?.physicsTick,
        physicsSubstep: execution?.physicsSubstep,
        positionEpoch: execution?.positionEpoch,
        topologyEpoch: execution?.topologyEpoch,
        chartEpoch: execution?.chartEpoch,
        levelEpoch: execution?.levelEpoch,
        supportEpoch: execution?.supportEpoch,
        completionOrdinal: execution?.buildOrdinal,
        sourceCount: execution?.sourceCount,
        physicalSourceCount: execution?.physicalSourceCount
          ?? execution?.sourceCount,
        sourceRowLayoutId: execution?.sourceRowLayoutId,
        identityStrideWords: SPH_GPU_PARTICLE_IDENTITY_UINTS,
        selectedLevel,
        gridNodeCount: gridSpec?.gridNodeCount,
        gridDims: gridSpec?.gridDims,
        gridShift: gridSpec?.shift,
        gridSpacingM: Math.fround(Number(gridSpec?.gridSpacingM))
      }
    );
    try {
      mechanicsFieldViewOwnerAdmitted =
        mechanicsFieldViewRuntime === mechanicsFieldView?.ownerRuntime
        && mechanicsFieldViewRuntime?.ownsExecution?.(mechanicsFieldView) === true
        && mechanicsFieldViewRuntime?.isExecutionSubmitted?.(mechanicsFieldView) === true;
    } catch {
      mechanicsFieldViewOwnerAdmitted = false;
    }
    const fieldLayout = mechanicsFieldView?.layout || null;
    const expectedFieldByteLength = Number(fieldLayout?.byteLength);
    mechanicsFieldViewShapeAdmitted =
      mechanicsFieldView?.schema
        === ULG_SCHROEDER_SPATIAL_MECHANICS_FIELD_VIEW_SCHEMA
      && mechanicsFieldView?.sourceBuffer === execution?.sourceBuffer
      && mechanicsFieldView?.identityBuffer === particleIdentityBuffer
      && mechanicsFieldView?.parentMechanicsView === mechanicsView
      && (!directoryV2 || (
        mechanicsFieldView?.sourceAuthorityVersion
          === SCHROEDER_SPATIAL_MECHANICS_FIELD_SOURCE_AUTHORITY_V2
        && mechanicsFieldView?.spatialExecution === execution
        && mechanicsFieldView?.directoryBuffer === directoryBuffer
        && mechanicsFieldView?.activeSourceView === activeSourceView
        && mechanicsFieldView?.activeSourceViewBuffer === activeSourceBuffer
        && mechanicsFieldView?.activeSourceCountAuthority
          === execution?.activeSourceCountAuthority
        && mechanicsFieldView?.candidateCount === null
        && mechanicsFieldView?.stableCandidateOrderCount === null
        && mechanicsFieldView?.stableCandidateOrderCountAuthority?.buffer
          === activeSourceBuffer
        && mechanicsFieldView?.stableCandidateOrderCountAuthority?.offsetWords
          === 43
      ))
      && mechanicsFieldView?.fieldViewBuffer === mechanicsFieldView?.indirectDispatchBuffer
      && mechanicsFieldView?.indirectDispatchOffsetBytes
        === SCHROEDER_SPATIAL_MECHANICS_FIELD_VIEW_DISPATCH_OFFSET_WORDS
          * Uint32Array.BYTES_PER_ELEMENT
      && fieldLayout?.headerWords
        === SCHROEDER_SPATIAL_MECHANICS_FIELD_VIEW_HEADER_WORDS
      && fieldLayout?.sourceCapacity >= execution?.sourceCount
      && fieldLayout?.fieldCapacity >= mechanicsFieldView?.candidateCount
      && mechanicsFieldView?.stableCandidateOrderBuffer
      && mechanicsFieldView?.stableCandidateOrderCount
        === mechanicsFieldView?.candidateCount
      && mechanicsFieldView?.stableCandidateOrderPolicy
        === 'stable-radix-equal-key-preserves-particle-stencil-candidate-order'
      && mechanicsFieldView?.ownsStableCandidateOrderBuffer === false
      && (!Number.isFinite(Number(
        mechanicsFieldView?.stableCandidateOrderBuffer?.size
      )) || Number(mechanicsFieldView.stableCandidateOrderBuffer.size)
        >= mechanicsFieldView.candidateCount * Uint32Array.BYTES_PER_ELEMENT)
      && Number.isSafeInteger(expectedFieldByteLength)
      && expectedFieldByteLength === fieldLayout?.wordLength * Uint32Array.BYTES_PER_ELEMENT
      && (!Number.isFinite(Number(mechanicsFieldView?.fieldViewBuffer?.size))
        || Number(mechanicsFieldView.fieldViewBuffer.size) >= expectedFieldByteLength);
  }
  const mechanicsViewRejected = mechanicsViewPublished && (
    mechanicsViewAdmission?.admitted !== true
    || mechanicsViewDeviceMismatch.mismatch
    || !mechanicsViewOwnerAdmitted
    || !mechanicsViewShapeAdmitted
  );
  const mechanicsFieldViewRejected = mechanicsFieldViewPublished && (
    mechanicsFieldViewAdmission?.admitted !== true
    || mechanicsFieldViewDeviceMismatch.mismatch
    || !mechanicsFieldViewOwnerAdmitted
    || !mechanicsFieldViewShapeAdmitted
  );
  const activeSourceRejected = directoryV2 && (
    activeSourceAdmission?.admitted !== true
    || !activeSourceOwnerAdmitted
    || activeSourceDeviceMismatch.mismatch
    || !activeSourceBuffer
  );
  const schemaRejected = schroederSpatialEpochGeneration != null && (
    schroederSpatialEpochGeneration?.schema !== SCHROEDER_SPATIAL_EPOCH_GENERATION_SCHEMA
    || (
      execution?.schema !== SCHROEDER_SPATIAL_EPOCH_SCHEMA
      && !directoryV2
    )
  );
  const overlayRejected =
    schroederSpatialEpochGeneration?.source?.phaseVolumeAssignmentOverlayEnabled === true;
  const released = execution?.released === true;
  const queryProfileRejected = schroederSpatialEpochGeneration != null && (
    execution?.sourceAdapterId !== SCHROEDER_SPATIAL_SOURCE_ADAPTER_EXACT_NEAR_QUERY
    || execution?.exactNearQueryProfile?.ready !== true
    || execution?.queryGeometryEvidence !== execution?.exactNearQueryProfile
  );
  const canonicalIntent = canonicalSpatialRequired === true
    || schroederSpatialEpochGeneration?.selected === true;
  const enabled = schroederSpatialEpochGeneration?.selected === true
    && schroederSpatialEpochGeneration?.ready === true
    && !overlayRejected
    && execution?.submitPerformed === true
    && Boolean(directoryBuffer)
    && Boolean(evidenceBuffer)
    && !deviceMismatch.mismatch
    && !evidenceBufferTooSmall
    && !schemaRejected
    && !activeSourceRejected
    && !queryProfileRejected
    && !mechanicsViewRejected
    && !mechanicsFieldViewRejected
    && !released;
  if (!enabled) {
    const rejectionStatus = (() => {
      if (deviceMismatch.mismatch) {
        return 'canonical-spatial-directory-rejected-device';
      }
      if (activeSourceRejected) {
        return activeSourceAdmission?.status
          ?? 'canonical-spatial-active-source-rejected-owner';
      }
      if (mechanicsViewRejected) {
        if (mechanicsViewDeviceMismatch.mismatch) {
          return 'canonical-spatial-mechanics-view-rejected-device';
        }
        if (mechanicsViewAdmission?.admitted !== true) {
          return mechanicsViewAdmission?.status;
        }
        return mechanicsViewOwnerAdmitted
          ? 'canonical-spatial-mechanics-view-rejected-shape'
          : 'canonical-spatial-mechanics-view-rejected-owner';
      }
      if (mechanicsFieldViewRejected) {
        if (mechanicsFieldViewDeviceMismatch.mismatch) {
          return 'canonical-spatial-mechanics-field-view-rejected-device';
        }
        if (mechanicsFieldViewAdmission?.admitted !== true) {
          return mechanicsFieldViewAdmission?.status;
        }
        return mechanicsFieldViewOwnerAdmitted
          ? 'canonical-spatial-mechanics-field-view-rejected-shape'
          : 'canonical-spatial-mechanics-field-view-rejected-owner';
      }
      if (evidenceBufferTooSmall) {
        return 'canonical-spatial-directory-rejected-evidence-capacity';
      }
      if (overlayRejected) {
        return 'canonical-spatial-directory-rejected-overlay-authority';
      }
      if (schemaRejected) return 'canonical-spatial-directory-rejected-schema';
      if (queryProfileRejected) {
        return 'canonical-spatial-directory-rejected-query-geometry';
      }
      if (released) {
        return 'canonical-spatial-directory-rejected-released-generation';
      }
      return canonicalIntent
        ? 'canonical-spatial-directory-requested-but-unavailable'
        : 'canonical-spatial-directory-not-provided';
    })();
    if (canonicalIntent) {
      throw fusedCanonicalSpatialAuthorityError(
        rejectionStatus,
        `spatial authority was rejected before submission: ${rejectionStatus}`
      );
    }
    const buffer = sharedZeroPlaceholderBuffer(
      device,
      `${labelPrefix}-empty-schroeder-spatial-directory`,
      48 * Uint32Array.BYTES_PER_ELEMENT,
      GPU_BUFFER_USAGE.STORAGE | GPU_BUFFER_USAGE.COPY_DST
    );
    return {
      enabled: false,
      required: canonicalSpatialRequired === true,
      storageGeneration: 0,
      positionEpoch: 0,
      topologyEpoch: 0,
      deviceOrdinal: 0,
      laneOrdinal: 0,
      leaseToken: 0,
      sourceFamilyId: 0,
      physicsTick: 0,
      physicsSubstep: 0,
      chartEpoch: 0,
      levelEpoch: 0,
      supportEpoch: 0,
      activeNodeBuffer: buffer,
      directoryAbiVersion: SCHROEDER_SPATIAL_MECHANICS_VIEW_DIRECTORY_VERSION_V1,
      activeSourceV2Enabled: false,
      activeSourceP2gEnabled: false,
      activeSourceDenseSingleLevelEnabled: false,
      activeSourceView: null,
      activeSourceBuffer: null,
      activeSourceQueryMinLevel: null,
      activeSourceQueryMaxLevel: null,
      activeSourceCompletionOrdinal: 0,
      activeSourceActiveDispatchOffsetBytes: 0,
      evidenceBuffer: null,
      mechanicsViewEnabled: false,
      mechanicsViewBuffer: null,
      mechanicsViewIndirectDispatchBuffer: null,
      mechanicsViewIndirectDispatchOffsetBytes: 0,
      sourceRowLayoutId: 0,
      completionOrdinal: 0,
      mechanicsFieldViewEnabled: false,
      mechanicsFieldViewBuffer: null,
      mechanicsFieldViewIndirectDispatchBuffer: null,
      mechanicsFieldViewIndirectDispatchOffsetBytes: 0,
      // Shared per device; see the note on the dummy level assignments.
      ownsActiveNodeBuffer: false,
      retainedActiveNodeBuffer: false,
      activeNodeBufferByteLength: 48 * Uint32Array.BYTES_PER_ELEMENT,
      activeNodeBufferSource: 'dummy-schroeder-spatial-directory',
      evidenceBufferByteLength: 0,
      evidenceBufferSource: null,
      sourceDeviceId: deviceMismatch.sourceDeviceId,
      consumerDeviceId: deviceMismatch.consumerDeviceId,
      hostBindingAdmitted: false,
      hostBindingFallback: true,
      gpuAdmissionObserved: false,
      gpuAdmissionStatus: 'not-applicable-host-binding-fallback',
      gpuFallbackObserved: null,
      status: rejectionStatus
    };
  }
  const mechanicsViewEnabled = consumeCompactMechanicsView !== false
    && mechanicsViewPublished
    && mechanicsViewAdmission?.admitted === true
    && mechanicsViewOwnerAdmitted
    && mechanicsViewShapeAdmitted
    && !mechanicsViewDeviceMismatch.mismatch;
  const authorityEvidenceBuffer = mechanicsViewEnabled
    ? mechanicsView.mechanicsViewBuffer
    : evidenceBuffer;
  const mechanicsFieldViewEnabled = mechanicsViewEnabled
    && mechanicsFieldViewPublished
    && mechanicsFieldViewAdmission?.admitted === true
    && mechanicsFieldViewOwnerAdmitted
    && mechanicsFieldViewShapeAdmitted
    && !mechanicsFieldViewDeviceMismatch.mismatch;
  return {
    enabled: true,
    required: canonicalSpatialRequired === true,
    storageGeneration: execution.storageGeneration,
    positionEpoch: execution.positionEpoch,
    topologyEpoch: execution.topologyEpoch,
    deviceOrdinal: execution.deviceOrdinal,
    laneOrdinal: execution.laneOrdinal,
    leaseToken: execution.leaseToken,
    sourceFamilyId: execution.sourceFamilyId,
    physicsTick: execution.physicsTick,
    physicsSubstep: execution.physicsSubstep,
    chartEpoch: execution.chartEpoch,
    levelEpoch: execution.levelEpoch,
    supportEpoch: execution.supportEpoch,
    generationId: execution.generationId,
    activeNodeBuffer: directoryBuffer,
    directoryAbiVersion: directoryV2
      ? SCHROEDER_SPATIAL_MECHANICS_VIEW_DIRECTORY_VERSION_V2
      : SCHROEDER_SPATIAL_MECHANICS_VIEW_DIRECTORY_VERSION_V1,
    activeSourceV2Enabled: directoryV2,
    activeSourceP2gEnabled: directoryV2 && mechanicsFieldViewEnabled,
    activeSourceDenseSingleLevelEnabled: directoryV2
      && mechanicsViewEnabled
      && Number.isInteger(activeSourceView?.queryMinLevel)
      && activeSourceView.queryMinLevel === selectedLevel
      && activeSourceView.queryMaxLevel === selectedLevel
      && execution?.queryMinLevel === selectedLevel
      && execution?.queryMaxLevel === selectedLevel,
    activeSourceView: directoryV2 ? activeSourceView : null,
    activeSourceBuffer: directoryV2 ? activeSourceBuffer : null,
    activeSourceQueryMinLevel: directoryV2
      ? activeSourceView.queryMinLevel
      : null,
    activeSourceQueryMaxLevel: directoryV2
      ? activeSourceView.queryMaxLevel
      : null,
    activeSourceCompletionOrdinal: directoryV2
      ? activeSourceView.buildOrdinal
      : 0,
    activeSourceActiveDispatchOffsetBytes: directoryV2
      ? activeSourceView.activeDispatchOffsetBytes
      : 0,
    activeSourceCandidateDispatchOffsetBytes: directoryV2
      ? activeSourceView.candidateDispatchOffsetBytes
      : 0,
    activeSourcePhysicalDispatchOffsetBytes: directoryV2
      ? activeSourceView.physicalDispatchOffsetBytes
      : 0,
    activeSourcePhysicalCapacity: directoryV2
      ? activeSourceView.physicalSourceCapacity
      : 0,
    activeSourceActiveCapacity: directoryV2
      ? activeSourceView.activeSourceCapacity
      : 0,
    activeSourceViewWordLength: directoryV2
      ? activeSourceView.layout.wordLength
      : 0,
    activeSourceActiveToPhysicalOffsetWords: directoryV2
      ? activeSourceView.layout.activeToPhysicalOffsetWords
      : 0,
    activeSourcePhysicalToActiveOffsetWords: directoryV2
      ? activeSourceView.layout.physicalToActiveOffsetWords
      : 0,
    activeSourceFingerprint: directoryV2
      ? activeSourceView.sourceFingerprint
      : 0,
    activeSourceDispatchXLimit: directoryV2
      ? activeSourceView.layout?.dispatchXLimit
        ?? activeSourceView.dispatchXLimit
        ?? device?.limits?.maxComputeWorkgroupsPerDimension
        ?? 65535
      : 0,
    evidenceBuffer: authorityEvidenceBuffer,
    mechanicsViewEnabled,
    mechanicsViewExecution: mechanicsViewEnabled ? mechanicsView : null,
    mechanicsViewBuffer: mechanicsViewEnabled ? mechanicsView.mechanicsViewBuffer : null,
    mechanicsViewIndirectDispatchBuffer: mechanicsViewEnabled
      ? mechanicsView.indirectDispatchBuffer
      : null,
    mechanicsViewIndirectDispatchOffsetBytes: mechanicsViewEnabled
      ? mechanicsView.indirectDispatchOffsetBytes
      : 0,
    mechanicsViewNodeCapacity: mechanicsViewEnabled ? mechanicsView.nodeCapacity : 0,
    mechanicsViewByteLength: mechanicsViewEnabled ? mechanicsView.layout.byteLength : 0,
    sourceRowLayoutId: mechanicsViewEnabled ? mechanicsView.sourceRowLayoutId : 0,
    completionOrdinal: mechanicsViewEnabled ? mechanicsView.completionOrdinal : 0,
    mechanicsFieldViewEnabled,
    mechanicsFieldViewExecution: mechanicsFieldViewEnabled
      ? mechanicsFieldView
      : null,
    mechanicsFieldViewBuffer: mechanicsFieldViewEnabled
      ? mechanicsFieldView.fieldViewBuffer
      : null,
    mechanicsFieldViewIndirectDispatchBuffer: mechanicsFieldViewEnabled
      ? mechanicsFieldView.indirectDispatchBuffer
      : null,
    mechanicsFieldViewIndirectDispatchOffsetBytes: mechanicsFieldViewEnabled
      ? mechanicsFieldView.indirectDispatchOffsetBytes
      : 0,
    mechanicsFieldViewByteLength: mechanicsFieldViewEnabled
      ? mechanicsFieldView.layout.byteLength
      : 0,
    mechanicsFieldViewLayout: mechanicsFieldViewEnabled
      ? mechanicsFieldView.layout
      : null,
    mechanicsFieldSourceDispatchWorkgroups: mechanicsFieldViewEnabled
      ? mechanicsFieldView.sourceDispatchWorkgroups
      : null,
    mechanicsFieldCandidateDispatchWorkgroups: mechanicsFieldViewEnabled
      ? mechanicsFieldView.candidateDispatchWorkgroups
      : null,
    mechanicsFieldIndirectDispatchDimensions:
      mechanicsFieldViewEnabled ? 2 : 0,
    mechanicsFieldIndirectDispatchLinearization:
      mechanicsFieldViewEnabled
        ? 'linearGroup=workgroup.x+workgroup.y*dispatchX'
        : null,
    ownsActiveNodeBuffer: false,
    retainedActiveNodeBuffer: true,
    activeNodeBufferByteLength: execution.layout?.byteLength
      ?? directoryBuffer.size
      ?? 0,
    activeNodeBufferSource: 'retained-schroeder-spatial-directory',
    evidenceBufferByteLength: mechanicsViewEnabled
      ? mechanicsView.layout.byteLength
      : (execution.evidenceBufferByteLength
        ?? evidenceBuffer.size
        ?? SCHROEDER_SPATIAL_EPOCH_WITH_MECHANICS_EVIDENCE_BYTES),
    evidenceBufferSource: mechanicsViewEnabled
      ? 'generation-owned-schroeder-compact-mechanics-view-buffer'
      : 'generation-owned-schroeder-spatial-evidence-buffer',
    sourceDeviceId: deviceMismatch.sourceDeviceId,
    consumerDeviceId: deviceMismatch.consumerDeviceId,
    hostBindingAdmitted: true,
    hostBindingFallback: false,
    gpuAdmissionObserved: false,
    gpuAdmissionStatus: 'shader-validates-at-dispatch-no-host-readback',
    gpuFallbackObserved: null,
    status: mechanicsViewEnabled
      ? 'canonical-spatial-compact-mechanics-view-bound-for-grid-dispatch'
      : 'canonical-spatial-directory-bound-for-p2g-level-admission'
  };
}

